/**
 * Encryption vault for PII columns.
 *
 * `@tsir/vault` encrypts PII (e.g. `users.tax_id`) with AES-256-GCM. The
 * active key normally comes from the `APP_KEY_NOW` environment variable (a
 * `<id>:<alg>:<base64url-material>` spec generated by `tsir vault:key:generate`).
 *
 * For local dev and tests, a key is generated on import so the app boots
 * without a secret. **This means encrypted data does not survive a restart in
 * dev** — set `APP_KEY_NOW` in production via the app config.
 *
 * The vault exposes `encrypt(plaintext)` and `decrypt(envelope)`; a
 * `VaultColumnCodec` adapts it to a Drizzle column so the encryption is
 * invisible to application code.
 */
import { createVaultBootstrap } from '@tsir/vault';
import appConfig from '../../../config/vault.ts';

export const { vault, vaultToken, vaultProvider } = createVaultBootstrap({
  config: appConfig,
});
